    "step1_desc": "Začínáš s <strong>10 000 zl.</strong> Skupuj 12 sad Koní, Psů a Sokolů (nájmy až 80 %, bonus <strong>+1,5 💖</strong> za ucelenou sadu) a hospodářská stáda ve stájích (ovce, prasata, skot), která trvale zvyšují výnosy tvých Vesnic, Měst a Hradů!",
