    "step2_desc": "U obchodníka zbroj a u mistrů trénuj <strong>Boj</strong> (lov monster a draků), <strong>Jízdu</strong> (sprint, trysk, obcházení mýtného a Závody), <strong>Tanec</strong> (audience u krále, Zámecké plesy) a <strong>Charisma</strong> (násobí všechna získaná srdce)!",
    "step3_title": "🐉 Lov draků nebo vláda statkáře",
    "step3_desc": "Na políčkách Úkolů bojuj s divokou zvěří a skoli obávaného Draka (za 2 draky okamžitý triumf!). Nebo jdi cestou velkostatkáře – 3 největší chovatelé zvířat drží královskou prémii až <strong>+4,0 💖</strong>!",
    "step4_title": "💖 Zazář na Slavnostech a vyhraj",
    "step4_desc": "Vstup na <strong>Turnaj, Zámecký ples nebo Velký závod</strong> a získej obrovské příděly srdcí. Rytíř, který jako první dosáhne <strong>30 💖</strong>, slaví královskou svatbu a vyhrává partii!",
    "guest_banner": "🏰 <strong>Vstup do hry:</strong> Hraj ihned volně bez registrace, nebo se přihlas svým rytířským profilem:",
    "preview_ticker_default": "🏰 Živý průlet nad herním plánem (96 polí)",
