    "goal_title": "Cíl hry a podmínka vítězství",
    "goal_desc": "Vítězem se stává rytíř, který jako první dosáhne <strong>30 💖 Princezniných srdcí</strong>, nebo který jako nepřemožitelný hrdina <strong>skolí 2 obávané draky království</strong> (okamžitý dračí triumf)!",
    "loop_title": "Průběh tahu ve 4 krocích",
    "loop_lead": "Každý tah rytíře probíhá ve stejném přehledném pořadí:",
    "step1_title": "Hod kostkou",
    "step1_desc": "Hoď 1d6 pro standardní pochod, zvol opatrný krok (1–4), nebo naskoč na koně pro bleskový klus, cval či trysk.",
    "step2_title": "Pohyb & Rozcestí",
    "step2_desc": "Postupuj vpřed. Dorazíš-li na rozcestí, figurka se zastaví a <strong>ty sám si zvolíš směr</strong> (vnější vsi vs. vnitřní královská stezka).",
    "step3_title": "Akce na cílovém poli",
    "step3_desc": "Kup volné panství / zaplať nájem sokovi / trénuj u Mistra / vstup do arény draků / zúčastni se královské slavnosti!",
    "step4_title": "Konec tahu",
    "step4_desc": "Předání tahu dalšímu rytíři v pořadí. Můžeš také aktivovat pergamen z brašny nebo zkontrolovat stav svého panství.",
    "three_paths_title": "Tři rovnocenné cesty k vítězství",
    "path_warrior_title": "⚔️ Válečník & Lovec draků",
    "path_warrior_desc": "Trénuje Boj, nakupuje zbraně a zbroj. Loví zvěř (U1), monstra (U2) a poráží 2 draky království (U3) pro okamžitý triumf bez nutnosti sbírat srdce!",
    "path_breeder_title": "🐎 Chovatel & Velkostatkář",
    "path_breeder_desc": "Skupuje zvířata stejné sady (Kůň, Pes, Sokol) pro 80% nájemné, buduje stáje s hospodářským dobytkem a povyšuje vesnice na nedobytné tvrze.",
    "path_courtier_title": "👑 Dvořan & Diplomat",
    "path_courtier_desc": "Trénuje Tanec a Charisma, navštěvuje zámecké plesy a slavnosti. Při každé návštěvě STARTu získává královskou audienci a násobí veškeré zisky srdcí!",
    "step1_badge": "KROK 1",
    "step2_badge": "KROK 2",
    "step3_badge": "KROK 3",
    "step4_badge": "KROK 4",
    "path_warrior_header": "⚔️ 1. Cesta Válečníka",
    "path_warrior_points": "• Investuj do ctnosti <strong>Boj</strong>, kováren a zbraní.<br/>• Plň úkoly netvorů U1–U2 a dominuj na <strong>Turnajích</strong>.<br/>• <strong>Dračí triumf:</strong> Skolením 2 draků okamžitě vyhráváš hru bez ohledu na počet srdcí!",
    "path_breeder_header": "🐎 2. Cesta Chovatele",
    "path_breeder_points": "• Skupuj trojice zvířat (kůň + pes + sokol) pro bonus <strong>+1,5 💖</strong>.<br/>• Nakupuj hospodářská stáda ve stájích (ovce, prasata, skot).<br/>• Drž 1. místo v <strong>Chovatelské prémii (+4,0 💖)</strong> a vyhrávej Velké závody.",
    "path_diplomat_header": "💃 3. Cesta Diplomata",
    "path_diplomat_points": "• Investuj do <strong>Tance, Charismatu a plesových šatů</strong>.<br/>• Audience u krále na STARTu a Hradě (<strong>+0,5 až +1,0 💖</strong>).<br/>• Drť soupeře na <strong>Zámeckých plesech</strong> (až +5 💖 a 1 200 zl. za vítězství).",
    "tips_title": "💡 5 zlatých rad pro začínajícího lorda",
    "tip1": "<strong>Pořiď si koně co nejdříve:</strong> Zpřístupní ti 2 kostky pro pohyb, umožní rychlý cval a otevře vstup do Velkého závodu.",
    "tip2": "<strong>Rozcestí je tvá strategie:</strong> Vnější okruh skýtá vesnice a zvířata; vnitřní královská stezka nabízí mistry ctností, arény draků a slavnosti.",
    "tip3": "<strong>Slavnosti jsou klíčem k srdcím:</strong> Sleduj podmínky účasti na Turnaji, Plese a Závodě. 1. místo dává obrovský skok v srdcích!",
    "tip4": "<strong>Chraň se před zraněním:</strong> V boji s monstry používej postoj <em>Opatrná obrana</em> za štítem, nebo si v lazaretu kup <em>Hojivý elixír</em> s ochranným amuletem.",
    "tip5": "<strong>Sbírej pečetě mistrů:</strong> Zisk 3 různých pečetí ti udělí <em>Rytířskou záštitu</em> – osvobození od válečných daní a ošetření v lazaretu zdarma!",
