    "title": "Legenda o unesené princezně a rubínovém náhrdelníku",
    "subtitle": "Od sokolího poselství a přísahy u dvora až po záchranu princezny z dračí sluje — každé tvoje rozhodnutí na plánu píše pokračování této ságy.",
