    "beat2_title": "2. Únos z audience & Dračí sluj",
    "beat2_desc": "Blesk rozetne královskou síň a drak unese princeznu do horských slují. Plačící královna svírá rubínové srdce, zatímco rytíř s pážetem přísahají záchranu.",
    "beat3_title": "3. Zkouška šampionů & Rubínová pocta",
    "beat3_desc": "Nad deskou se spojí ruce hrdinů. Ten, kdo jako první prokáže hodnotu a dosáhne cíle výpravy (výchozí <strong>30 💖</strong>), položí draka a získá ruku princezny i královskou korunu.",
    "paths_title": "⚔️ Tři cesty k vítězství (Jak získat 30 💖)",
    "path1_title": "🏰 Panství & Šlechtické chovy",
    "path1_desc": "Kupuj koně, psy a sokoly, rozšiřuj vesnice v města a hrady a pobírej královské výnosy.",
    "path2_title": "🎭 Ctnosti & Slavnosti dvora",
    "path2_desc": "Studuj u mistrů Čest, Boj, Jízdu a Tanec a oslň královský dvůr na plesech i turnajích.",
    "path3_title": "🐉 Zápas s monstry & Dračí sluj",
    "path3_desc": "Vyzbroj se v kovárnách, utkej se s lesními obludami a slož hlavu draka princezně k nohám.",
    "video_ch1_badge": "🎬 Kapitola I • Realistická",
    "video_ch1_title": "Sokolí poselství & Dračí souboj",
    "video_ch1_desc": "Osamělá princezna s rudým náhrdelníkem vyšle sokola. Rytíř s koněm a psem přijímá zprávu, porazí draka v jeho sluji a přinese princezně dračí hlavu k nohám.",
    "video_ch2_badge": "🎲 Kapitola II • Desková hra",
    "video_ch2_title": "Čtyři šampioni nad herním plánem",
    "video_ch2_desc": "Dva rytíři, sokolník a šlechtična vrhnou kostky nad herním plánem. Nad královstvím přeletí stín draka a nad rubínovým srdcem se spojí čtyři ruce hrdinů.",
    "video_ch3_badge": "🎨 Kapitola III • Kreslená sága",
    "video_ch3_title": "Únos princezny & Návrat s fanfárami",
    "video_ch3_desc": "Drak rozbije okno audience a unese princeznu. Rytíř a páže se sokolem i psem přísahají záchranu, přemohou draka a vrací se k fanfárám i rubínovému náhrdelníku.",
